mapper.insert:
insert into analytics_rollup_watermarks(
    job_name, watermark_at, generated_at, status, message,
    coverage_start, coverage_end, attribution_mode, version
) values (
    #{jobName}, #{watermarkAt}, #{generatedAt}, #{status}, #{message},
    #{coverageStart}, #{coverageEnd}, #{attributionMode}, #{version}
)

mapper.select:
select if(reason_code = '', 'OTHER', reason_code) as reason_code, count() as reason_count
from analytics_feedback_facts final where  and rating = 'NEGATIVE'
group by reason_code order by reason_count desc limit #{limit}

select run_id, user_id, username, organization, rd_department, department,
       workspace_id, agent_id, model_id, status,
       occurred_at as created_at, occurred_at as updated_at
from analytics_activity_facts final where  and status in ('FAILED', 'CANCELLED')
order by occurred_at desc limit #{limit} offset #{offset}

select

    if(rd_department = '', '未归属', rd_department)
    if(department = '', '未归属', department)
    if(organization = '', '未归属', organization)

as name,
count() as registered_users,
countIf(status = 'ACTIVE') as enabled_users
from analytics_user_dimensions final where status != 'DELETED'

group by name order by name

select distinct department as value, department as label
from analytics_user_dimensions final where status != 'DELETED' and department != ''
and organization = #{organization}
and rd_department = #{rdDepartment}
order by label
